  1→import { patchState, signalStore, withMethods, withState } from "@ngrx/signals";
  2→import type {
  3→  ScenarioContent,
  4→  ScenarioEventDef,
  5→  ScenarioIssueDef,
  6→  DecisionTemplateDef,
  7→  RoleDef,
  8→} from "../../core/scenario-api.service";
  9→
 10→interface ScenarioBuilderState {
 11→  scenarioId: number | null;
 12→  title: string;
 13→  description: string;
 14→  content: ScenarioContent;
 15→  saving: boolean;
 16→  error: string | null;
 17→  loadedSnapshot: string | null;
 18→}
 19→
 20→const emptyContent: ScenarioContent = {
 21→  phases: [],
 22→  events: [],
 23→  issues: [],
 24→  decision_templates: [],
 25→  default_time_factor: 1.0,
 26→  briefing: "",
 27→  objectives: [],
 28→  rules: [],
 29→  roles: [],
 30→  game_mode: "classic",
 31→  turns: [],
 32→  initial_system_states: [],
 33→};
 34→
 35→export const ScenarioBuilderStore = signalStore(
 36→  withState<ScenarioBuilderState>({
 37→    scenarioId: null,
 38→    title: "",
 39→    description: "",
 40→    content: emptyContent,
 41→    saving: false,
 42→    error: null,
 43→    loadedSnapshot: null,
 44→  }),
 45→
 46→  withMethods((store) => ({
 47→    loadScenario(
 48→      id: number,
 49→      title: string,
 50→      description: string,
 51→      content: ScenarioContent | null,
 52→    ): void {
 53→      const c = content ?? emptyContent;
 54→      const snapshot = JSON.stringify({ title, description, content: c });
 55→      patchState(store, {
 56→        scenarioId: id,
 57→        title,
 58→        description,
 59→        content: c,
 60→        loadedSnapshot: snapshot,
 61→      });
 62→    },
 63→
 64→    loadImport(
 65→      title: string,
 66→      description: string,
 67→      content: ScenarioContent,
 68→    ): void {
 69→      patchState(store, {
 70→        scenarioId: null,
 71→        title,
 72→        description,
 73→        content,
 74→        loadedSnapshot: null,
 75→        error: null,
 76→      });
 77→    },
 78→
 79→    revert(): void {
 80→      const snap = store.loadedSnapshot();
 81→      if (!snap) return;
 82→      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- JSON boundary
 83→      const { title, description, content } = JSON.parse(snap) as {
 84→        title: string;
 85→        description: string;
 86→        content: ScenarioContent;
 87→      };
 88→      patchState(store, { title, description, content });
 89→    },
 90→
 91→    setTitle(title: string): void {
 92→      patchState(store, { title });
 93→    },
 94→
 95→    setDescription(description: string): void {
 96→      patchState(store, { description });
 97→    },
 98→
 99→    setTimeFactor(factor: number): void {
100→      patchState(store, {
101→        content: { ...store.content(), default_time_factor: factor },
102→      });
103→    },
104→
105→    addEvent(event: ScenarioEventDef): void {
106→      patchState(store, {
107→        content: {
108→          ...store.content(),
109→          events: [...store.content().events, event],
110→        },
111→      });
112→    },
113→
114→    removeEvent(eventId: string): void {
115→      patchState(store, {
