 4→  DomainConfigApiService,
 5→  type DomainConfigResponse,
 6→  type TerminologyMap,
 7→} from "./domain-config-api.service";
 8→
 9→const FALLBACK_TERMINOLOGY: TerminologyMap = {
10→  event: "Event",
11→  issue: "Issue",
12→  player: "Player",
13→  gameMaster: "Game Master",
14→  exercise: "Exercise",
15→  scenario: "Scenario",
16→  decision: "Decision",
17→};
18→
19→const FALLBACK_DOMAIN: DomainConfigResponse = {
20→  id: 0,
21→  slug: "default",
22→  name: "Default",
23→  description: "",
24→  terminology: FALLBACK_TERMINOLOGY,
25→  theme: {
26→    colorPrimary: "#3b82f6",
27→    colorSecondary: "#6366f1",
28→    colorBackground: "#ffffff",
29→    colorForeground: "#1e293b",
30→    fontFamily: "system-ui, sans-serif",
31→    fontFamilyMono: "ui-monospace, monospace",
32→    density: "comfortable",
33→  },
34→  roles: [],
35→  severity_levels: [],
36→  created_at: "",
37→  updated_at: "",
38→};
39→
40→@Injectable({ providedIn: "root" })
41→export class DomainService {
42→  private readonly api = inject(DomainConfigApiService);
43→
44→  readonly activeDomain = signal<DomainConfigResponse>(FALLBACK_DOMAIN);
45→  readonly availableDomains = signal<DomainConfigResponse[]>([]);
46→  readonly loading = signal(false);
47→
48→  constructor() {
49→    this.loadAll();
50→  }
51→
52→  async loadAll(): Promise<void> {
53→    this.loading.set(true);
54→    try {
55→      const domains = await firstValueFrom(this.api.list());
56→      this.availableDomains.set(domains);
57→      const current = domains.find((d) => d.slug === this.activeDomain().slug);
58→      if (current) {
59→        this.activeDomain.set(current);
60→      }
61→    } finally {
62→      this.loading.set(false);
63→    }
64→  }
65→
66→  async setDomain(slugOrId: string | number): Promise<void> {
67→    const cached = this.availableDomains().find((d) =>
68→      typeof slugOrId === "number" ? d.id === slugOrId : d.slug === slugOrId,
69→    );
70→    if (cached) {
71→      this.activeDomain.set(cached);
72→      this.applyTheme(cached.slug);
73→      return;
74→    }
75→    const fetched =
76→      typeof slugOrId === "number"
77→        ? await firstValueFrom(this.api.get(slugOrId))
78→        : await firstValueFrom(this.api.getBySlug(slugOrId));
79→    this.activeDomain.set(fetched);
80→    this.applyTheme(fetched.slug);
81→  }
82→
83→  term(key: keyof TerminologyMap): string {
84→    return this.activeDomain().terminology[key] ?? key;
85→  }
86→
87→  private applyTheme(slug: string): void {
88→    const themeAttr = `tfc-${slug}`;
89→    const html = document.documentElement;
90→    html.setAttribute("data-theme", themeAttr);
91→  }
92→}
