  1→import { patchState, signalStore, withMethods, withState } from "@ngrx/signals";
  2→import type {
  3→  ScenarioContent,
  4→  ScenarioEventDef,
  5→  ScenarioIssueDef,
  6→  DecisionTemplateDef,
  7→  RoleDef,
  8→} from "../../core/scenario-api.service";
  9→
 10→interface ScenarioBuilderState {
 11→  scenarioId: number | null;
 12→  title: string;
 13→  description: string;
 14→  content: ScenarioContent;
 15→  saving: boolean;
 16→  error: string | null;
 17→  loadedSnapshot: string | null;
 18→}
 19→
 20→const emptyContent: ScenarioContent = {
 21→  phases: [],
 22→  events: [],
 23→  issues: [],
 24→  decision_templates: [],
 25→  default_time_factor: 1.0,
 26→  briefing: "",
 27→  objectives: [],
 28→  rules: [],
 29→  roles: [],
 30→  game_mode: "classic",
 31→  turns: [],
 32→  initial_system_states: [],
 33→};
 34→
 35→export const ScenarioBuilderStore = signalStore(
 36→  withState<ScenarioBuilderState>({
 37→    scenarioId: null,
 38→    title: "",
 39→    description: "",
 40→    content: emptyContent,
 41→    saving: false,
 42→    error: null,
 43→    loadedSnapshot: null,
 44→  }),
 45→
 46→  withMethods((store) => ({
 47→    loadScenario(
 48→      id: number,
 49→      title: string,
 50→      description: string,
 51→      content: ScenarioContent | null,
 52→    ): void {
 53→      const c = content ?? emptyContent;
 54→      const snapshot = JSON.stringify({ title, description, content: c });
 55→      patchState(store, {
 56→        scenarioId: id,
 57→        title,
 58→        description,
 59→        content: c,
 60→        loadedSnapshot: snapshot,
 61→      });
 62→    },
 63→
 64→    loadImport(
 65→      title: string,
 66→      description: string,
 67→      content: ScenarioContent,
 68→    ): void {
 69→      patchState(store, {
 70→        scenarioId: null,
 71→        title,
 72→        description,
 73→        content,
 74→        loadedSnapshot: null,
 75→        error: null,
 76→      });
 77→    },
 78→
 79→    revert(): void {
 80→      const snap = store.loadedSnapshot();
 81→      if (!snap) return;
 82→      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- JSON boundary
 83→      const { title, description, content } = JSON.parse(snap) as {
 84→        title: string;
 85→        description: string;
 86→        content: ScenarioContent;
 87→      };
 88→      patchState(store, { title, description, content });
 89→    },
 90→
 91→    setTitle(title: string): void {
 92→      patchState(store, { title });
 93→    },
 94→
 95→    setDescription(description: string): void {
 96→      patchState(store, { description });
 97→    },
 98→
 99→    setTimeFactor(factor: number): void {
100→      patchState(store, {
101→        content: { ...store.content(), default_time_factor: factor },
102→      });
103→    },
104→
105→    addEvent(event: ScenarioEventDef): void {
106→      patchState(store, {
107→        content: {
108→          ...store.content(),
109→          events: [...store.content().events, event],
110→        },
111→      });
112→    },
113→
114→    removeEvent(eventId: string): void {
115→      patchState(store, {
116→        content: {
117→          ...store.content(),
118→          events: store.content().events.filter((e) => e.id !== eventId),
119→        },
120→      });
121→    },
122→
123→    updateEvent(eventId: string, updates: Partial<ScenarioEventDef>): void {
124→      patchState(store, {
125→        content: {
126→          ...store.content(),
127→          events: store
128→            .content()
129→            .events.map((e) => (e.id === eventId ? { ...e, ...updates } : e)),
130→        },
131→      });
132→    },
133→
134→    addIssue(issue: ScenarioIssueDef): void {
135→      patchState(store, {
136→        content: {
137→          ...store.content(),
138→          issues: [...store.content().issues, issue],
139→        },
140→      });
141→    },
142→
143→    removeIssue(issueId: string): void {
144→      patchState(store, {
145→        content: {
146→          ...store.content(),
147→          issues: store.content().issues.filter((i) => i.id !== issueId),
148→        },
149→      });
150→    },
151→
152→    updateIssue(issueId: string, updates: Partial<ScenarioIssueDef>): void {
153→      patchState(store, {
154→        content: {
155→          ...store.content(),
156→          issues: store
157→            .content()
158→            .issues.map((i) => (i.id === issueId ? { ...i, ...updates } : i)),
159→        },
160→      });
161→    },
162→
163→    addDecisionTemplate(template: DecisionTemplateDef): void {
164→      patchState(store, {
165→        content: {
166→          ...store.content(),
167→          decision_templates: [...store.content().decision_templates, template],
168→        },
169→      });
170→    },
171→
172→    removeDecisionTemplate(templateId: string): void {
173→      patchState(store, {
174→        content: {
175→          ...store.content(),
176→          decision_templates: store
177→            .content()
178→            .decision_templates.filter((d) => d.id !== templateId),
179→        },
180→      });
181→    },
182→
183→    updateDecisionTemplate(
184→      templateId: string,
185→      updates: Partial<DecisionTemplateDef>,
186→    ): void {
187→      patchState(store, {
188→        content: {
189→          ...store.content(),
190→          decision_templates: store
191→            .content()
192→            .decision_templates.map((d) =>
193→              d.id === templateId ? { ...d, ...updates } : d,
194→            ),
195→        },
196→      });
197→    },
198→
199→    addRole(role: RoleDef): void {
200→      patchState(store, {
201→        content: {
202→          ...store.content(),
203→          roles: [...(store.content().roles ?? []), role],
204→        },
205→      });
206→    },
207→
208→    removeRole(roleId: string): void {
209→      patchState(store, {
210→        content: {
211→          ...store.content(),
212→          roles: (store.content().roles ?? []).filter((r) => r.id !== roleId),
213→        },
214→      });
215→    },
216→
217→    updateRole(roleId: string, updates: Partial<RoleDef>): void {
218→      patchState(store, {
219→        content: {
220→          ...store.content(),
221→          roles: (store.content().roles ?? []).map((r) =>
222→            r.id === roleId ? { ...r, ...updates } : r,
223→          ),
224→        },
225→      });
226→    },
227→
228→    setBriefing(briefing: string): void {
229→      patchState(store, {
230→        content: { ...store.content(), briefing },
231→      });
232→    },
233→
234→    setSaving(saving: boolean): void {
235→      patchState(store, { saving });
236→    },
237→
238→    setError(error: string): void {
239→      patchState(store, { error, saving: false });
240→    },
241→
242→    clearError(): void {
243→      patchState(store, { error: null });
244→    },
245→
246→    reset(): void {
247→      patchState(store, {
248→        scenarioId: null,
249→        title: "",
250→        description: "",
251→        content: emptyContent,
252→        saving: false,
253→        error: null,
254→        loadedSnapshot: null,
255→      });
256→    },
257→  })),
258→);
