import type {
  ScenarioContent,
  ScenarioEventDef,
  ScenarioIssueDef,
  DecisionTemplateDef,
  RoleDef,
  TurnDefinition,
  TurnInjectDef,
  TurnCardConfig,
} from "../../core/scenario-api.service";

addTurn(turn: TurnDefinition): void {
  const turns = store.content().turns ?? [];
  const newTurn = { ...turn, turn_index: turns.length };
  patchState(store, {
    content: { ...store.content(), turns: [...turns, newTurn] },
  });
},

removeTurn(turnIndex: number): void {
  const turns = (store.content().turns ?? [])
    .filter((t) => t.turn_index !== turnIndex)
    .map((t, i) => ({ ...t, turn_index: i }));
  patchState(store, {
    content: { ...store.content(), turns },
  });
},

updateTurn(turnIndex: number, updates: Partial<TurnDefinition>): void {
  const turns = (store.content().turns ?? []).map((t) =>
    t.turn_index === turnIndex ? { ...t, ...updates } : t,
  );
  patchState(store, {
    content: { ...store.content(), turns },
  });
},

reorderTurns(fromIndex: number, toIndex: number): void {
  const turns = [...(store.content().turns ?? [])];
  const [moved] = turns.splice(fromIndex, 1);
  turns.splice(toIndex, 0, moved);
  const renumbered = turns.map((t, i) => ({ ...t, turn_index: i }));
  patchState(store, {
    content: { ...store.content(), turns: renumbered },
  });
},

duplicateTurn(turnIndex: number): void {
  const turns = [...(store.content().turns ?? [])];
  const source = turns.find((t) => t.turn_index === turnIndex);
  if (!source) return;
  const clone = { ...source, title: `${source.title} (copy)` };
  turns.splice(turnIndex + 1, 0, clone);
  const renumbered = turns.map((t, i) => ({ ...t, turn_index: i }));
  patchState(store, {
    content: { ...store.content(), turns: renumbered },
  });
},

addInjectToTurn(turnIndex: number, inject: TurnInjectDef): void {
  const turns = (store.content().turns ?? []).map((t) =>
    t.turn_index === turnIndex
      ? { ...t, injects: [...t.injects, inject] }
      : t,
  );
  patchState(store, {
    content: { ...store.content(), turns },
  });
},

removeInjectFromTurn(turnIndex: number, injectIndex: number): void {
  const turns = (store.content().turns ?? []).map((t) =>
    t.turn_index === turnIndex
      ? { ...t, injects: t.injects.filter((_, i) => i !== injectIndex) }
      : t,
  );
  patchState(store, {
    content: { ...store.content(), turns },
  });
},

updateInjectInTurn(
  turnIndex: number,
  injectIndex: number,
  updates: Partial<TurnInjectDef>,
): void {
  const turns = (store.content().turns ?? []).map((t) =>
    t.turn_index === turnIndex
      ? {
          ...t,
          injects: t.injects.map((inj, i) =>
            i === injectIndex ? { ...inj, ...updates } : inj,
          ),
        }
      : t,
  );
  patchState(store, {
    content: { ...store.content(), turns },
  });
},

addCardToTurn(turnIndex: number, cardConfig: TurnCardConfig): void {
  const turns = (store.content().turns ?? []).map((t) =>
    t.turn_index === turnIndex
      ? { ...t, available_cards: [...t.available_cards, cardConfig] }
      : t,
  );
  patchState(store, {
    content: { ...store.content(), turns },
  });
},

removeCardFromTurn(turnIndex: number, cardId: string): void {
  const turns = (store.content().turns ?? []).map((t) =>
    t.turn_index === turnIndex
      ? {
          ...t,
          available_cards: t.available_cards.filter(
            (c) => c.card_id !== cardId,
          ),
        }
      : t,
  );
  patchState(store, {
    content: { ...store.content(), turns },
  });
},

updateCardInTurn(
  turnIndex: number,
  cardId: string,
  updates: Partial<TurnCardConfig>,
): void {
  const turns = (store.content().turns ?? []).map((t) =>
    t.turn_index === turnIndex
