116→export class HomeView implements OnInit {
117→  private readonly http = inject(HttpClient);
118→  private readonly router = inject(Router);
119→  private readonly exerciseApi = inject(ExerciseApiService);
120→  private readonly engineApi = inject(EngineApiService);
121→  private readonly waitingRoomApi = inject(WaitingRoomApiService);
122→
123→  protected readonly lobbyData = signal<JoinableExercise[]>([]);
124→  protected readonly showPicker = signal(false);
125→  protected readonly pendingScenario = signal<ScenarioResponse | null>(null);
126→
127→  ngOnInit(): void {
128→    this.checkForJoinableExercises();
129→  }
130→
131→  protected onScenarioPicked(scenario: ScenarioResponse): void {
132→    const gameMode = scenario.content?.game_mode ?? "classic";
133→    if (gameMode === "simple_collaborative") {
134→      this.showPicker.set(false);
135→      this.pendingScenario.set(scenario);
136→      return;
137→    }
138→    this.createAndShowLobby(scenario, false);
139→  }
140→
141→  protected createMultiplayer(playerCountMode: "full" | "two_player"): void {
142→    const scenario = this.pendingScenario();
143→    if (!scenario) return;
144→    this.pendingScenario.set(null);
145→    this.createAndShowLobby(scenario, false, playerCountMode);
146→  }
147→
148→  protected createPractice(): void {
149→    const scenario = this.pendingScenario();
150→    if (!scenario) return;
151→    this.pendingScenario.set(null);
152→    const gameMode = scenario.content?.game_mode ?? "simple_collaborative";
153→
154→    this.exerciseApi
155→      .create({
156→        title: scenario.title,
157→        scenario_id: scenario.id,
158→        game_mode: gameMode,
159→        practice_mode: true,
160→      })
161→      .pipe(
162→        switchMap((exercise) =>
163→          this.waitingRoomApi.join(exercise.id, "Player", "all_roles").pipe(
164→            switchMap((participant) =>
165→              this.engineApi.start(exercise.id).pipe(
166→                switchMap(() => {
167→                  this.router.navigate(["/player"], {
168→                    queryParams: {
169→                      exerciseId: exercise.id,
170→                      participantId: participant.id,
171→                      role: "all_roles",
172→                      gameMode: "simple_collaborative",
173→                      practiceMode: true,
174→                    },
175→                  });
176→                  return [];
177→                }),
178→              ),
179→            ),
180→          ),
181→        ),
182→      )
183→      .subscribe();
184→  }
185→
186→  private createAndShowLobby(
187→    scenario: ScenarioResponse,
188→    practiceMode: boolean,
189→    playerCountMode?: "full" | "two_player",
190→  ): void {
191→    const gameMode = scenario.content?.game_mode ?? "classic";
192→    this.exerciseApi
193→      .create({
194→        title: scenario.title,
195→        scenario_id: scenario.id,
196→        game_mode: gameMode,
197→        practice_mode: practiceMode,
198→      })
199→      .subscribe({
200→        next: (exercise) => {
201→          this.router.navigate(["/waiting-room"], {
202→            queryParams: {
203→              exerciseId: exercise.id,
204→              ...(playerCountMode ? { playerCountMode } : {}),
205→            },
206→          });
207→        },
208→      });
209→  }
210→
211→  protected joinExercise(): void {
212→    this.router.navigate(["/waiting-room"], {
213→      queryParams: { browse: true },
214→    });
215→  }
216→
217→  private checkForJoinableExercises(): void {
218→    this.http
219→      .get<
220→        JoinableExercise[]
221→      >(`${environment.apiBaseUrl}/api/exercises/joinable`)
222→      .subscribe({
223→        next: (data) => this.lobbyData.set(data),
224→        error: () => this.lobbyData.set([]),
225→      });
226→  }
227→}
