 36→@Component({
 37→  selector: "tfc-sea-backdrop",
 38→  changeDetection: ChangeDetectionStrategy.OnPush,
 39→  styles: [
 40→    `
 41→      :host {
 42→        display: block;
 43→        position: absolute;
 44→        inset: 0;
 45→        pointer-events: none;
 46→        overflow: hidden;
 47→      }
 48→
 49→      canvas {
 50→        display: block;
 51→        width: 100%;
 52→        height: 100%;
 53→      }
 54→    `,
 55→  ],
 56→  template: `<canvas #canvas></canvas>`,
 57→})
 58→export class SeaBackdrop implements OnDestroy {
 59→  private readonly canvasRef =
 60→    viewChild.required<ElementRef<HTMLCanvasElement>>("canvas");
 61→  private renderer!: THREE.WebGLRenderer;
 62→  private scene!: THREE.Scene;
 63→  private camera!: THREE.PerspectiveCamera;
 64→  private plane!: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
 65→  private animationId = 0;
 66→  private resizeObserver!: ResizeObserver;
 67→
 68→  private signals: Signal[] = [];
 69→  private nextSpawn = 0;
 70→  private glowTexture!: THREE.Texture;
 71→
 72→  private convergences: Convergence[] = [];
 73→  private nextConvergence = 2;
 74→
 75→  private lightnings: Lightning[] = [];
 76→  private nextLightning = 1;
 77→
 78→  private get themeColor(): THREE.Color {
 79→    const raw = getComputedStyle(document.documentElement)
 80→      .getPropertyValue("--color-primary")
 81→      .trim();
 82→    return new THREE.Color(
 83→      raw.startsWith("oklch") ? 0x1ac5c5 : raw || 0x1ac5c5,
 84→    );
 85→  }
 86→
 87→  constructor(private ngZone: NgZone) {
 88→    afterNextRender(() => {
 89→      this.initScene();
 90→      this.ngZone.runOutsideAngular(() => this.animate(0));
 91→    });
 92→  }
 93→
 94→  ngOnDestroy(): void {
 95→    cancelAnimationFrame(this.animationId);
 96→    this.resizeObserver?.disconnect();
 97→    this.renderer?.dispose();
 98→    this.plane?.geometry.dispose();
 99→    this.plane?.material.dispose();
100→    this.glowTexture?.dispose();
101→    for (const s of this.signals) {
102→      this.scene.remove(s.light, s.sprite);
103→      s.sprite.material.dispose();
104→    }
105→    for (const c of this.convergences) {
106→      disposeConvergence(this.scene, c);
107→    }
108→    for (const l of this.lightnings) {
109→      disposeLightning(this.scene, l);
110→    }
111→  }
112→
113→  private initScene(): void {
114→    const canvas = this.canvasRef().nativeElement;
115→    const w = canvas.clientWidth || 1;
116→    const h = canvas.clientHeight || 1;
117→
118→    this.renderer = new THREE.WebGLRenderer({
119→      canvas,
120→      alpha: true,
121→      antialias: true,
122→    });
123→    this.renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
124→    this.renderer.setSize(w, h, false);
125→
126→    const bgColor = new THREE.Color(0x061218);
127→    this.scene = new THREE.Scene();
128→    this.scene.background = bgColor;
129→    this.camera = new THREE.PerspectiveCamera(27, w / h, 0.1, 100);
130→    this.camera.position.set(0, 1.6, 5);
131→    this.camera.lookAt(0, -0.4, -2);
132→
133→    this.scene.add(new THREE.AmbientLight(0xffffff, 0.5));
134→    const dir = new THREE.DirectionalLight(0xffffff, 0.8);
135→    dir.position.set(-3, 5, 4);
136→    this.scene.add(dir);
137→
138→    const primary = this.themeColor;
139→    const pl1 = new THREE.PointLight(primary, 2.5, 20);
140→    pl1.position.set(0, 2, 3);
141→    const pl2 = new THREE.PointLight(primary, 1.5, 15);
142→    pl2.position.set(-4, 1, -2);
143→    this.scene.add(pl1, pl2);
144→
145→    const geo = new THREE.PlaneGeometry(24, 14, 180, 120);
146→    geo.rotateX(-Math.PI / 2);
147→    const mat = new THREE.MeshBasicMaterial({
148→      color: primary,
149→      wireframe: true,
150→      transparent: true,
151→      opacity: 0.08,
152→    });
153→    this.plane = new THREE.Mesh(geo, mat);
154→    this.plane.position.y = -0.3;
155→    this.scene.add(this.plane);
156→
157→    this.scene.fog = new THREE.Fog(bgColor, 8, 16);
158→    this.glowTexture = createGlowTexture();
159→    this.resizeObserver = new ResizeObserver(() => this.handleResize());
160→    this.resizeObserver.observe(canvas);
161→  }
162→
163→  // ── Signals ────────────────────────────────────────────
164→
165→  private spawnSignal(t: number): void {
166→    const types = [SignalType.Friendly, SignalType.Hostile, SignalType.Neutral];
167→    const type = types[Math.floor(Math.random() * types.length)];
168→    const color = SIGNAL_COLORS[type];
169→    const x = (Math.random() - 0.5) * 14;
170→    const z = (Math.random() - 0.5) * 8;
171→    const light = new THREE.PointLight(color, 0, 5);
172→    light.position.set(x, waveY(x, z, t), z);
173→    this.scene.add(light);
174→    const mat = new THREE.SpriteMaterial({
175→      map: this.glowTexture,
176→      color,
177→      transparent: true,
178→      opacity: 0,
179→      blending: THREE.AdditiveBlending,
180→      depthWrite: false,
181→    });
182→    const sprite = new THREE.Sprite(mat);
183→    sprite.scale.set(0.8, 0.8, 1);
184→    sprite.position.copy(light.position);
185→    this.scene.add(sprite);
186→    this.signals.push({ type, x, z, birth: t, light, sprite });
187→  }
188→
189→  private updateSignals(t: number): void {
190→    if (t >= this.nextSpawn && this.signals.length < MAX_SIGNALS) {
191→      this.spawnSignal(t);
192→      this.nextSpawn = t + SPAWN_INTERVAL + Math.random() * SPAWN_INTERVAL;
193→    }
194→
195→    for (let i = this.signals.length - 1; i >= 0; i--) {
196→      const s = this.signals[i];
197→      const age = t - s.birth;
198→      const life = age / SIGNAL_LIFESPAN;
199→
200→      if (life >= 1) {
201→        this.scene.remove(s.light, s.sprite);
202→        (s.sprite.material as THREE.SpriteMaterial).dispose();
203→        this.signals.splice(i, 1);
204→        continue;
205→      }
206→
207→      const fade =
208→        life < 0.15 ? life / 0.15 : life > 0.7 ? (1 - life) / 0.3 : 1;
209→
210→      const pulse = 1 + Math.sin(age * 4) * 0.2;
211→      const intensity = fade * pulse;
212→
213→      const y = waveY(s.x, s.z, t);
214→      s.light.position.set(s.x, y + 0.25, s.z);
215→      s.light.intensity = intensity * 3;
216→      s.sprite.position.set(s.x, y + 0.25, s.z);
217→      (s.sprite.material as THREE.SpriteMaterial).opacity = intensity * 0.9;
218→      s.sprite.scale.setScalar(0.5 + intensity * 0.4);
219→    }
220→  }
221→
222→  // ── Convergences ─────────────────────────────────────────
223→
224→  private updateConvergences(t: number): void {
225→    if (t >= this.nextConvergence) {
226→      this.convergences.push(
227→        createConvergence(
228→          this.scene,
229→          this.glowTexture,
230→          this.themeColor,
231→          this.plane.geometry,
232→          t,
233→        ),
234→      );
235→      this.nextConvergence = t + CONVERGENCE_INTERVAL + Math.random() * 2;
236→    }
237→    for (let i = this.convergences.length - 1; i >= 0; i--) {
238→      if (!updateConvergence(this.convergences[i], t)) {
239→        disposeConvergence(this.scene, this.convergences[i]);
240→        this.convergences.splice(i, 1);
241→      }
242→    }
243→  }
244→
245→  // ── Lightning bolts ─────────────────────────────────────
246→
247→  private updateLightnings(t: number): void {
248→    if (t >= this.nextLightning) {
249→      this.lightnings.push(
250→        createLightning(this.scene, this.plane.geometry, t),
251→      );
252→      this.nextLightning =
253→        t + LIGHTNING_INTERVAL + (Math.random() - 0.5) * 2;
254→    }
255→    for (let i = this.lightnings.length - 1; i >= 0; i--) {
256→      if (!updateLightning(this.lightnings[i], t)) {
257→        disposeLightning(this.scene, this.lightnings[i]);
258→        this.lightnings.splice(i, 1);
259→      }
260→    }
261→  }
262→
263→  // ── Core loop ──────────────────────────────────────────
264→
265→  private handleResize(): void {
266→    const canvas = this.canvasRef().nativeElement;
267→    const w = canvas.clientWidth;
268→    const h = canvas.clientHeight;
269→    this.camera.aspect = w / h;
270→    this.camera.updateProjectionMatrix();
271→    this.renderer.setSize(w, h, false);
272→  }
273→
274→  private animate(time: number): void {
275→    this.animationId = requestAnimationFrame((t) => this.animate(t));
276→
277→    const t = time * 0.001;
278→    const positions = this.plane.geometry.attributes["position"];
279→    const count = positions.count;
280→
281→    for (let i = 0; i < count; i++) {
282→      const x = positions.getX(i);
283→      const z = positions.getZ(i);
284→      positions.setY(i, waveY(x, z, t));
285→    }
286→
287→    positions.needsUpdate = true;
288→    this.plane.geometry.computeVertexNormals();
289→
290→    this.updateSignals(t);
291→    this.updateConvergences(t);
292→    this.updateLightnings(t);
293→    this.renderer.render(this.scene, this.camera);
294→  }
295→}
