179→          ...store.content(),
180→          decision_templates: store
181→            .content()
182→            .decision_templates.filter((d) => d.id !== templateId),
183→        },
184→      });
185→    },
186→
187→    updateDecisionTemplate(
188→      templateId: string,
189→      updates: Partial<DecisionTemplateDef>,
190→    ): void {
191→      patchState(store, {
192→        content: {
193→          ...store.content(),
194→          decision_templates: store
