254→    },
255→
256→    removeInjectFromTurn(turnIndex: number, injectIndex: number): void {
257→      patchState(store, { content: turnMut.removeInjectFromTurn(store.content(), turnIndex, injectIndex) });
258→    },
259→
260→    updateInjectInTurn(
261→      turnIndex: number,
262→      injectIndex: number,
263→      updates: Partial<TurnInjectDef>,
264→    ): void {
265→      patchState(store, { content: turnMut.updateInjectInTurn(store.content(), turnIndex, injectIndex, updates) });
266→    },
267→
268→    addCardToTurn(turnIndex: number, cardConfig: TurnCardConfig): void {
