  1→import type {
  2→  ScenarioContent,
  3→  TurnDefinition,
  4→  TurnInjectDef,
  5→  TurnCardConfig,
  6→} from "../../../core/scenario-api.service";
  7→
  8→/** Return a new content with the turn appended and its turn_index auto-set. */
  9→export function addTurn(
 10→  content: ScenarioContent,
 11→  turn: TurnDefinition,
 12→): ScenarioContent {
 13→  const turns = content.turns ?? [];
 14→  return { ...content, turns: [...turns, { ...turn, turn_index: turns.length }] };
 15→}
 16→
 17→/** Remove a turn by turn_index and renumber the remaining turns. */
 18→export function removeTurn(
 19→  content: ScenarioContent,
 20→  turnIndex: number,
 21→): ScenarioContent {
 22→  const turns = (content.turns ?? [])
 23→    .filter((t) => t.turn_index !== turnIndex)
 24→    .map((t, i) => ({ ...t, turn_index: i }));
 25→  return { ...content, turns };
 26→}
 27→
 28→/** Spread partial updates over the turn found by turn_index. */
 29→export function updateTurn(
 30→  content: ScenarioContent,
 31→  turnIndex: number,
 32→  updates: Partial<TurnDefinition>,
 33→): ScenarioContent {
 34→  const turns = (content.turns ?? []).map((t) =>
 35→    t.turn_index === turnIndex ? { ...t, ...updates } : t,
 36→  );
 37→  return { ...content, turns };
 38→}
 39→
 40→/** Move a turn from one array position to another and renumber all. */
 41→export function reorderTurns(
 42→  content: ScenarioContent,
 43→  fromIndex: number,
 44→  toIndex: number,
 45→): ScenarioContent {
 46→  const turns = [...(content.turns ?? [])];
 47→  const [moved] = turns.splice(fromIndex, 1);
 48→  turns.splice(toIndex, 0, moved);
 49→  const renumbered = turns.map((t, i) => ({ ...t, turn_index: i }));
 50→  return { ...content, turns: renumbered };
 51→}
 52→
 53→/** Clone the turn, insert after original, and renumber all subsequent. */
 54→export function duplicateTurn(
 55→  content: ScenarioContent,
 56→  turnIndex: number,
 57→): ScenarioContent {
 58→  const turns = [...(content.turns ?? [])];
 59→  const source = turns.find((t) => t.turn_index === turnIndex);
 60→  if (!source) return content;
 61→  const clone = { ...source, title: `${source.title} (copy)` };
 62→  turns.splice(turnIndex + 1, 0, clone);
 63→  const renumbered = turns.map((t, i) => ({ ...t, turn_index: i }));
 64→  return { ...content, turns: renumbered };
 65→}
 66→
 67→/** Append an inject to the specified turn's injects array. */
 68→export function addInjectToTurn(
 69→  content: ScenarioContent,
 70→  turnIndex: number,
 71→  inject: TurnInjectDef,
 72→): ScenarioContent {
 73→  const turns = (content.turns ?? []).map((t) =>
 74→    t.turn_index === turnIndex
 75→      ? { ...t, injects: [...t.injects, inject] }
 76→      : t,
 77→  );
 78→  return { ...content, turns };
 79→}
 80→
 81→/** Remove an inject by its position within the turn's injects array. */
 82→export function removeInjectFromTurn(
 83→  content: ScenarioContent,
 84→  turnIndex: number,
 85→  injectIndex: number,
 86→): ScenarioContent {
 87→  const turns = (content.turns ?? []).map((t) =>
 88→    t.turn_index === turnIndex
 89→      ? { ...t, injects: t.injects.filter((_, i) => i !== injectIndex) }
 90→      : t,
 91→  );
 92→  return { ...content, turns };
 93→}
 94→
 95→/** Update an inject by its position within the turn's injects array. */
 96→export function updateInjectInTurn(
 97→  content: ScenarioContent,
 98→  turnIndex: number,
 99→  injectIndex: number,
100→  updates: Partial<TurnInjectDef>,
101→): ScenarioContent {
102→  const turns = (content.turns ?? []).map((t) =>
103→    t.turn_index === turnIndex
104→      ? {
105→          ...t,
106→          injects: t.injects.map((inj, i) =>
107→            i === injectIndex ? { ...inj, ...updates } : inj,
108→          ),
109→        }
110→      : t,
111→  );
112→  return { ...content, turns };
113→}
114→
115→/** Append a card config to the specified turn's available_cards. */
116→export function addCardToTurn(
117→  content: ScenarioContent,
118→  turnIndex: number,
119→  cardConfig: TurnCardConfig,
120→): ScenarioContent {
121→  const turns = (content.turns ?? []).map((t) =>
122→    t.turn_index === turnIndex
123→      ? { ...t, available_cards: [...t.available_cards, cardConfig] }
124→      : t,
125→  );
126→  return { ...content, turns };
127→}
128→
129→/** Remove a card from the turn's available_cards by card_id. */
130→export function removeCardFromTurn(
131→  content: ScenarioContent,
132→  turnIndex: number,
133→  cardId: string,
134→): ScenarioContent {
135→  const turns = (content.turns ?? []).map((t) =>
136→    t.turn_index === turnIndex
137→      ? {
138→          ...t,
139→          available_cards: t.available_cards.filter(
140→            (c) => c.card_id !== cardId,
141→          ),
142→        }
143→      : t,
144→  );
145→  return { ...content, turns };
146→}
147→
148→/** Update a card in the turn's available_cards by card_id. */
149→export function updateCardInTurn(
150→  content: ScenarioContent,
151→  turnIndex: number,
152→  cardId: string,
153→  updates: Partial<TurnCardConfig>,
154→): ScenarioContent {
155→  const turns = (content.turns ?? []).map((t) =>
156→    t.turn_index === turnIndex
157→      ? {
158→          ...t,
159→          available_cards: t.available_cards.map((c) =>
160→            c.card_id === cardId ? { ...c, ...updates } : c,
161→          ),
162→        }
163→      : t,
164→  );
165→  return { ...content, turns };
166→}
