156→export class ScenarioBuilderView implements OnInit {
157→  protected readonly store = inject(ScenarioBuilderStore);
158→  private readonly api = inject(ScenarioApiService);
159→  protected readonly scenarios = signal<{ id: number; title: string }[]>([]);
160→
161→  protected readonly viewMode = signal<"global" | "walkthrough">("global");
162→
163→  protected readonly isDirty = computed(() => {
164→    const snap = this.store.loadedSnapshot();
165→    if (!snap) return false;
166→    const current = JSON.stringify({
167→      title: this.store.title(),
168→      description: this.store.description(),
169→      content: this.store.content(),
170→    });
171→    return current !== snap;
172→  });
173→
174→  protected readonly sidebarSections = computed<SidebarSection[]>(() => {
175→    const c = this.store.content();
176→    return [
177→      { id: "roles", label: "Roles", count: (c.roles ?? []).length },
178→      { id: "events", label: "Events", count: c.events.length },
179→      { id: "issues", label: "Issues", count: c.issues.length },
180→      {
181→        id: "decisions",
182→        label: "Decisions",
183→        count: c.decision_templates.length,
184→      },
185→      { id: "turns", label: "Turns", count: (c.turns ?? []).length },
186→      { id: "settings", label: "Settings", count: 0 },
187→    ];
188→  });
189→
190→  ngOnInit(): void {
191→    this.loadList();
192→  }
193→
194→  private loadList(): void {
195→    this.api.list().subscribe({
196→      next: (list) =>
197→        this.scenarios.set(list.map((s) => ({ id: s.id, title: s.title }))),
198→    });
199→  }
200→
201→  protected loadScenario(id: number): void {
202→    this.api.get(id).subscribe({
203→      next: (s) =>
204→        this.store.loadScenario(s.id, s.title, s.description, s.content),
205→    });
206→  }
207→
208→  protected save(): void {
209→    this.store.clearError();
210→    const content = this.store.content();
211→    const errors = validateScenarioContent(content);
212→    if (!this.store.title().trim()) errors.unshift("Title is required.");
213→    if (errors.length > 0) {
214→      this.store.setError(errors.join("\n"));
215→      return;
216→    }
217→    this.store.setSaving(true);
218→    const payload = {
219→      title: this.store.title(),
220→      description: this.store.description(),
221→      content,
222→    };
223→    const id = this.store.scenarioId();
224→    const req = id ? this.api.update(id, payload) : this.api.create(payload);
225→    req.subscribe({
226→      next: (s) => {
227→        this.store.loadScenario(s.id, s.title, s.description, s.content);
228→        this.store.setSaving(false);
229→        this.loadList();
230→      },
231→      error: () =>
232→        this.store.setError("Save failed — server rejected the scenario."),
233→    });
234→  }
235→
236→  protected saveAsCopy(): void {
237→    const id = this.store.scenarioId();
238→    if (!id) return;
239→    this.store.setSaving(true);
240→    this.api.clone(id).subscribe({
241→      next: (s) => {
242→        this.store.loadScenario(s.id, s.title, s.description, s.content);
243→        this.store.setSaving(false);
244→        this.loadList();
245→      },
246→      error: () => {
247→        this.store.setSaving(false);
248→        this.store.setError("Clone failed.");
249→      },
250→    });
251→  }
252→
253→  protected deleteScenario(id: number): void {
254→    this.api.delete(id).subscribe({ next: () => this.loadList() });
255→  }
256→}
