import type {
  DomainConfigResponse,
  DomainRole,
  SystemDef,
  WarfareDomainDef,
  BlueCardDef,
} from "../../../core/domain-config-api.service";

// ── Role mutations ──────────────────────────────────────────

export function addRole(
  config: DomainConfigResponse,
  role: DomainRole,
): DomainConfigResponse {
  return { ...config, roles: [...config.roles, role] };
}

export function removeRole(
  config: DomainConfigResponse,
  roleId: string,
): DomainConfigResponse {
  return { ...config, roles: config.roles.filter((r) => r.id !== roleId) };
}

export function updateRole(
  config: DomainConfigResponse,
  roleId: string,
  updates: Partial<DomainRole>,
): DomainConfigResponse {
  return {
    ...config,
    roles: config.roles.map((r) =>
      r.id === roleId ? { ...r, ...updates } : r,
    ),
  };
}

// ── System mutations ────────────────────────────────────────

export function addSystem(
  config: DomainConfigResponse,
  system: SystemDef,
): DomainConfigResponse {
  return { ...config, systems: [...config.systems, system] };
}

export function removeSystem(
  config: DomainConfigResponse,
  systemId: string,
): DomainConfigResponse {
  return {
    ...config,
    systems: config.systems.filter((s) => s.id !== systemId),
  };
}

export function updateSystem(
  config: DomainConfigResponse,
  systemId: string,
  updates: Partial<SystemDef>,
): DomainConfigResponse {
  return {
    ...config,
    systems: config.systems.map((s) =>
      s.id === systemId ? { ...s, ...updates } : s,
    ),
  };
}

// ── Warfare Domain mutations ────────────────────────────────

export function addWarfareDomain(
  config: DomainConfigResponse,
  domain: WarfareDomainDef,
): DomainConfigResponse {
  return { ...config, warfare_domains: [...config.warfare_domains, domain] };
}

export function removeWarfareDomain(
  config: DomainConfigResponse,
  domainId: string,
): DomainConfigResponse {
  return {
    ...config,
    warfare_domains: config.warfare_domains.filter((d) => d.id !== domainId),
  };
}

export function updateWarfareDomain(
  config: DomainConfigResponse,
  domainId: string,
  updates: Partial<WarfareDomainDef>,
): DomainConfigResponse {
  return {
    ...config,
    warfare_domains: config.warfare_domains.map((d) =>
      d.id === domainId ? { ...d, ...updates } : d,
    ),
  };
}

// ── Blue Card mutations ─────────────────────────────────────

export function addBlueCard(
  config: DomainConfigResponse,
  card: BlueCardDef,
): DomainConfigResponse {
  return { ...config, blue_card_catalog: [...config.blue_card_catalog, card] };
}

export function removeBlueCard(
  config: DomainConfigResponse,
  cardId: string,
): DomainConfigResponse {
  return {
    ...config,
    blue_card_catalog: config.blue_card_catalog.filter((c) => c.id !== cardId),
  };
}

export function updateBlueCard(
  config: DomainConfigResponse,
  cardId: string,
  updates: Partial<BlueCardDef>,
): DomainConfigResponse {
  return {
    ...config,
    blue_card_catalog: config.blue_card_catalog.map((c) =>
      c.id === cardId ? { ...c, ...updates } : c,
    ),
  };
}

import { patchState, signalStore, withMethods, withState } from "@ngrx/signals";
import type {
  DomainConfigResponse,
  DomainRole,
  SystemDef,
  WarfareDomainDef,
  BlueCardDef,
} from "../../core/domain-config-api.service";
import * as mut from "./domain/foundation-mutations";

interface FoundationState {
  config: DomainConfigResponse | null;
  loading: boolean;
  saving: boolean;
  error: string | null;
}

export const FoundationStore = signalStore(
  withState<FoundationState>({
    config: null,
    loading: false,
    saving: false,
    error: null,
  }),

  withMethods((store) => ({
    setConfig(config: DomainConfigResponse): void {
      patchState(store, { config, loading: false, error: null });
    },

    setLoading(loading: boolean): void {
      patchState(store, { loading });
    },

    setSaving(saving: boolean): void {
      patchState(store, { saving });
    },

    setError(error: string): void {
      patchState(store, { error, saving: false, loading: false });
    },

    clearError(): void {
      patchState(store, { error: null });
    },

    // ── Role CRUD ─────────────────────────────────────────

    addRole(role: DomainRole): void {
      const config = store.config();
      if (!config) return;
      patchState(store, { config: mut.addRole(config, role) });
    },

    removeRole(roleId: string): void {
      const config = store.config();
      if (!config) return;
      patchState(store, { config: mut.removeRole(config, roleId) });
    },

    updateRole(roleId: string, updates: Partial<DomainRole>): void {
      const config = store.config();
      if (!config) return;
      patchState(store, { config: mut.updateRole(config, roleId, updates) });
    },

    // ── System CRUD ───────────────────────────────────────

    addSystem(system: SystemDef): void {
      const config = store.config();
      if (!config) return;
      patchState(store, { config: mut.addSystem(config, system) });
    },

    removeSystem(systemId: string): void {
      const config = store.config();
      if (!config) return;
      patchState(store, { config: mut.removeSystem(config, systemId) });
    },

    updateSystem(systemId: string, updates: Partial<SystemDef>): void {
      const config = store.config();
      if (!config) return;
      patchState(store, {
        config: mut.updateSystem(config, systemId, updates),
      });
    },

    // ── Warfare Domain CRUD ───────────────────────────────

    addWarfareDomain(domain: WarfareDomainDef): void {
      const config = store.config();
      if (!config) return;
      patchState(store, { config: mut.addWarfareDomain(config, domain) });
    },

    removeWarfareDomain(domainId: string): void {
      const config = store.config();
      if (!config) return;
      patchState(store, {
        config: mut.removeWarfareDomain(config, domainId),
      });
    },

    updateWarfareDomain(
      domainId: string,
      updates: Partial<WarfareDomainDef>,
    ): void {
      const config = store.config();
      if (!config) return;
      patchState(store, {
        config: mut.updateWarfareDomain(config, domainId, updates),
      });
    },

    // ── Blue Card CRUD ────────────────────────────────────

    addBlueCard(card: BlueCardDef): void {
      const config = store.config();
      if (!config) return;
      patchState(store, { config: mut.addBlueCard(config, card) });
    },

    removeBlueCard(cardId: string): void {
      const config = store.config();
      if (!config) return;
      patchState(store, { config: mut.removeBlueCard(config, cardId) });
    },

    updateBlueCard(cardId: string, updates: Partial<BlueCardDef>): void {
      const config = store.config();
      if (!config) return;
      patchState(store, {
        config: mut.updateBlueCard(config, cardId, updates),
      });
    },
  })),
);

import { Routes } from "@angular/router";
import { FoundationView } from "./foundation-view";

export const FOUNDATION_ROUTES: Routes = [
  {
    path: "",
    component: FoundationView,
