 81→export class ScenarioBuilderActionsComponent {
 82→  protected readonly store = inject(ScenarioBuilderStore);
 83→  protected readonly fileInput =
 84→    viewChild<ElementRef<HTMLInputElement>>("fileInput");
 85→
 86→  readonly viewMode = input.required<"global" | "walkthrough">();
 87→  readonly isDirty = input(false);
 88→
 89→  readonly onSave = output<void>();
 90→  readonly onSaveAsCopy = output<void>();
 91→  readonly onToggleView = output<void>();
 92→
 93→  protected triggerFileInput(): void {
 94→    this.fileInput()?.nativeElement?.click();
 95→  }
 96→
 97→  protected exportJson(): void {
 98→    const title = this.store.title() || "scenario";
 99→    const safeTitle = title.replace(/[^a-zA-Z0-9_-]/g, "_");
100→    const blob = exportScenarioToJson(
101→      this.store.title(),
102→      this.store.description(),
103→      this.store.content(),
104→    );
105→    const url = URL.createObjectURL(blob);
106→    const a = document.createElement("a");
107→    a.href = url;
108→    a.download = `${safeTitle}.json`;
109→    a.click();
110→    URL.revokeObjectURL(url);
111→  }
112→
113→  protected onFileSelected(event: Event): void {
114→    const input = event.target;
115→    if (!(input instanceof HTMLInputElement)) return;
116→    const file = input.files?.[0];
117→    if (!file) return;
118→    file.text().then((text) => {
119→      const result = parseScenarioImport(text);
120→      if (!result) {
121→        this.store.setError("Invalid scenario JSON file.");
122→        return;
123→      }
124→      this.store.loadImport(result.title, result.description, result.content);
125→    });
126→    input.value = "";
127→  }
128→}
