  1→import { patchState, signalStore, withMethods, withState } from "@ngrx/signals";
  2→import type {
  3→  ScenarioContent,
  4→  ScenarioEventDef,
  5→  ScenarioIssueDef,
  6→  DecisionTemplateDef,
  7→  RoleDef,
  8→  TurnDefinition,
  9→  TurnInjectDef,
 10→  TurnCardConfig,
 11→} from "../../core/scenario-api.service";
 12→import * as turnMut from "./domain/turn-mutations";
 13→
 14→interface ScenarioBuilderState {
 15→  scenarioId: number | null;
 16→  title: string;
 17→  description: string;
 18→  content: ScenarioContent;
 19→  saving: boolean;
 20→  error: string | null;
 21→  loadedSnapshot: string | null;
 22→}
 23→
 24→const emptyContent: ScenarioContent = {
 25→  phases: [],
 26→  events: [],
 27→  issues: [],
 28→  decision_templates: [],
 29→  default_time_factor: 1.0,
 30→  briefing: "",
 31→  objectives: [],
 32→  rules: [],
 33→  roles: [],
 34→  game_mode: "classic",
 35→  turns: [],
 36→  initial_system_states: [],
 37→};
 38→
 39→export const ScenarioBuilderStore = signalStore(
 40→  withState<ScenarioBuilderState>({
 41→    scenarioId: null,
 42→    title: "",
 43→    description: "",
 44→    content: emptyContent,
 45→    saving: false,
 46→    error: null,
 47→    loadedSnapshot: null,
 48→  }),
 49→
 50→  withMethods((store) => ({
 51→    loadScenario(
 52→      id: number,
 53→      title: string,
 54→      description: string,
 55→      content: ScenarioContent | null,
 56→    ): void {
 57→      const c = content ?? emptyContent;
 58→      const snapshot = JSON.stringify({ title, description, content: c });
 59→      patchState(store, {
 60→        scenarioId: id,
 61→        title,
 62→        description,
 63→        content: c,
 64→        loadedSnapshot: snapshot,
 65→      });
 66→    },
 67→
 68→    loadImport(
 69→      title: string,
 70→      description: string,
 71→      content: ScenarioContent,
 72→    ): void {
 73→      patchState(store, {
 74→        scenarioId: null,
 75→        title,
 76→        description,
 77→        content,
 78→        loadedSnapshot: null,
 79→        error: null,
 80→      });
 81→    },
 82→
 83→    revert(): void {
 84→      const snap = store.loadedSnapshot();
 85→      if (!snap) return;
 86→      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- JSON boundary
 87→      const { title, description, content } = JSON.parse(snap) as {
 88→        title: string;
 89→        description: string;
 90→        content: ScenarioContent;
 91→      };
 92→      patchState(store, { title, description, content });
 93→    },
 94→
 95→    setTitle(title: string): void {
 96→      patchState(store, { title });
 97→    },
 98→
 99→    setDescription(description: string): void {
100→      patchState(store, { description });
101→    },
102→
103→    setTimeFactor(factor: number): void {
104→      patchState(store, {
105→        content: { ...store.content(), default_time_factor: factor },
106→      });
107→    },
108→
109→    addEvent(event: ScenarioEventDef): void {
110→      patchState(store, {
111→        content: {
112→          ...store.content(),
113→          events: [...store.content().events, event],
114→        },
115→      });
116→    },
117→
118→    removeEvent(eventId: string): void {
119→      patchState(store, {
120→        content: {
121→          ...store.content(),
122→          events: store.content().events.filter((e) => e.id !== eventId),
123→        },
124→      });
125→    },
126→
127→    updateEvent(eventId: string, updates: Partial<ScenarioEventDef>): void {
128→      patchState(store, {
129→        content: {
130→          ...store.content(),
131→          events: store
132→            .content()
133→            .events.map((e) => (e.id === eventId ? { ...e, ...updates } : e)),
134→        },
135→      });
136→    },
137→
138→    addIssue(issue: ScenarioIssueDef): void {
139→      patchState(store, {
