 60→  });
 61→
 62→  describe("addTurn", () => {
 63→    it("should append a turn and auto-set turn_index", () => {
 64→      store.addTurn(makeTurn({ title: "Alpha" }));
 65→      store.addTurn(makeTurn({ title: "Bravo" }));
 66→
 67→      const turns = store.content().turns ?? [];
 68→      expect(turns.length).toBe(2);
 69→      expect(turns[0].turn_index).toBe(0);
 70→      expect(turns[0].title).toBe("Alpha");
