 75→
 76→  describe("removeTurn", () => {
 77→    it("should remove a turn and renumber remaining", () => {
 78→      store.addTurn(makeTurn({ title: "A" }));
 79→      store.addTurn(makeTurn({ title: "B" }));
 80→      store.addTurn(makeTurn({ title: "C" }));
 81→
 82→      store.removeTurn(1);
 83→
 84→      const turns = store.content().turns ?? [];
 85→      expect(turns.length).toBe(2);
 86→      expect(turns[0].title).toBe("A");
 87→      expect(turns[0].turn_index).toBe(0);
 88→      expect(turns[1].title).toBe("C");
 89→      expect(turns[1].turn_index).toBe(1);
 90→    });
 91→  });
 92→
 93→  describe("updateTurn", () => {
 94→    it("should update title and leave other fields unchanged", () => {
 95→      store.addTurn(makeTurn({ title: "Original", design_notes: "keep me" }));
 96→
 97→      store.updateTurn(0, { title: "Updated" });
 98→
 99→      const turn = (store.content().turns ?? [])[0];
100→      expect(turn.title).toBe("Updated");
101→      expect(turn.design_notes).toBe("keep me");
102→    });
103→  });
104→
105→  describe("reorderTurns", () => {
106→    it("should move a turn and renumber all", () => {
107→      store.addTurn(makeTurn({ title: "A" }));
108→      store.addTurn(makeTurn({ title: "B" }));
109→      store.addTurn(makeTurn({ title: "C" }));
110→
111→      store.reorderTurns(0, 2);
112→
113→      const turns = store.content().turns ?? [];
114→      expect(turns.map((t) => t.title)).toEqual(["B", "C", "A"]);
115→      expect(turns.map((t) => t.turn_index)).toEqual([0, 1, 2]);
116→    });
117→  });
118→
119→  describe("duplicateTurn", () => {
120→    it("should clone the turn, insert after original, and renumber", () => {
121→      store.addTurn(makeTurn({ title: "First" }));
122→      store.addTurn(makeTurn({ title: "Second" }));
123→
124→      store.duplicateTurn(0);
