import {
  ChangeDetectionStrategy,
  Component,
  computed,
  inject,
  OnInit,
  signal,
} from "@angular/core";
import { RouterLink } from "@angular/router";
import {
  ButtonDirective,
  CardComponent,
  CollapsiblePanelComponent,
} from "@aspect/ui";
import {
  DomainConfigApiService,
  type DomainConfigResponse,
} from "../../core/domain-config-api.service";
import type {
  SystemStateDef,
  ScenarioWarfareDomainDef,
} from "../../core/scenario-api.service";
import { ScenarioBuilderStore } from "./scenario-builder.store";

@Component({
  selector: "tfc-scenario-setup-tab",
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    ButtonDirective,
    CardComponent,
    CollapsiblePanelComponent,
    RouterLink,
  ],
  template: `
    <!-- Section 1: Foundation Summary -->
    <section id="section-foundation" style="scroll-margin-top: var(--spacing-xl)">
      <ui-card title="Foundation">
        @if (domainConfig()) {
          <div class="flex flex-col gap-sm p-sm">
            <p class="text-sm text-muted-foreground">
              {{ domainConfig()!.roles.length }} roles &middot;
              {{ domainConfig()!.systems.length }} systems &middot;
              {{ domainConfig()!.warfare_domains.length }} warfare domains &middot;
              {{ domainConfig()!.blue_card_catalog.length }} blue cards
            </p>
            <a routerLink="/foundation" class="text-sm font-medium">
              Edit Foundation &rarr;
            </a>
            <ui-collapsible-panel>
              <span panelTitle>Preview catalogs</span>
              <div class="flex flex-col gap-sm p-sm">
                <div>
                  <span class="text-sm font-medium">Roles:</span>
                  <ul class="text-sm text-muted-foreground ml-md">
                    @for (r of domainConfig()!.roles; track r.id) {
                      <li>{{ r.label }}</li>
                    }
                  </ul>
                </div>
                <div>
                  <span class="text-sm font-medium">Systems:</span>
                  <ul class="text-sm text-muted-foreground ml-md">
                    @for (s of domainConfig()!.systems; track s.id) {
                      <li>{{ s.label }} ({{ s.category }})</li>
                    }
                  </ul>
                </div>
                <div>
                  <span class="text-sm font-medium">Warfare Domains:</span>
                  <ul class="text-sm text-muted-foreground ml-md">
                    @for (d of domainConfig()!.warfare_domains; track d.id) {
                      <li>{{ d.label }}</li>
                    }
                  </ul>
                </div>
              </div>
            </ui-collapsible-panel>
          </div>
        } @else {
          <p class="text-sm text-muted-foreground p-sm">
            Loading foundation data...
          </p>
        }
      </ui-card>
    </section>

    <!-- Section 2: Scenario Metadata -->
    <section id="section-metadata" style="scroll-margin-top: var(--spacing-xl)">
      <ui-card title="Scenario Metadata">
        <div class="flex flex-col gap-md p-sm">
          <!-- Briefing -->
          <div class="flex flex-col gap-xs">
            <label class="text-sm font-medium" for="briefing">Briefing</label>
            <textarea
              id="briefing"
              class="input-base"
              rows="5"
              [value]="store.content().briefing ?? ''"
              (input)="onBriefingChange($event)"
            ></textarea>
          </div>

          <!-- Objectives -->
          <div class="flex flex-col gap-xs">
            <span class="text-sm font-medium">Objectives</span>
            @for (obj of objectives(); track $index) {
              <div class="flex items-center gap-sm">
                <span class="text-sm text-muted-foreground" style="min-width: 1.5rem">
                  {{ $index + 1 }}.
                </span>
                <input
                  class="input-base"
                  style="flex: 1"
                  [value]="obj"
                  (input)="onObjectiveChange($index, $event)"
                />
                <button
                  uiButton
                  variant="destructive"
                  size="sm"
                  (click)="removeObjective($index)"
                >
                  Remove
                </button>
              </div>
            }
            <button uiButton variant="outline" size="sm" (click)="addObjective()">
              Add objective
            </button>
          </div>

          <!-- Rules -->
          <div class="flex flex-col gap-xs">
            <span class="text-sm font-medium">Rules</span>
            @for (rule of rules(); track $index) {
              <div class="flex items-center gap-sm">
                <span class="text-sm text-muted-foreground" style="min-width: 1.5rem">
                  {{ $index + 1 }}.
                </span>
                <input
                  class="input-base"
                  style="flex: 1"
                  [value]="rule"
                  (input)="onRuleChange($index, $event)"
                />
                <button
                  uiButton
                  variant="destructive"
                  size="sm"
                  (click)="removeRule($index)"
                >
                  Remove
                </button>
              </div>
            }
            <button uiButton variant="outline" size="sm" (click)="addRule()">
              Add rule
            </button>
          </div>

          <!-- Game Mode -->
          <div class="flex flex-col gap-xs">
            <span class="text-sm font-medium">Game Mode</span>
            <div class="flex gap-sm">
              <button
                uiButton
                [variant]="gameMode() === 'classic' ? 'default' : 'outline'"
                size="sm"
                (click)="store.setGameMode('classic')"
              >
                Classic
              </button>
              <button
                uiButton
                [variant]="gameMode() === 'collaborative' ? 'default' : 'outline'"
                size="sm"
                (click)="store.setGameMode('collaborative')"
              >
                Collaborative
              </button>
            </div>
          </div>

          <!-- Score Tier Thresholds -->
          <div class="flex flex-col gap-xs">
            <span class="text-sm font-medium">Score Tier Thresholds</span>
            <div class="flex gap-sm items-center">
              <label class="text-sm" for="threshold-lo">Lo</label>
              <input
                id="threshold-lo"
                type="number"
                class="input-base"
                style="width: 5rem"
                [value]="thresholdLo()"
                (change)="onThresholdLoChange($event)"
              />
              <label class="text-sm" for="threshold-mid">Mid</label>
              <input
                id="threshold-mid"
                type="number"
                class="input-base"
                style="width: 5rem"
                [value]="thresholdMid()"
                (change)="onThresholdMidChange($event)"
              />
            </div>
          </div>

          <!-- Default Time Factor -->
          <div class="flex items-center gap-sm">
            <label class="text-sm font-medium" for="time-factor">
              Default Time Factor
            </label>
            <input
              id="time-factor"
              type="number"
              class="input-base"
              style="width: 5rem"
              [value]="store.content().default_time_factor"
              (change)="onTimeFactorChange($event)"
            />
          </div>
        </div>
      </ui-card>
    </section>

    <!-- Section 3: Initial State Overrides -->
    <section id="section-initial-states" style="scroll-margin-top: var(--spacing-xl)">
      <ui-card title="Initial State Overrides">
        <div class="flex flex-col gap-md p-sm">
          @if (domainConfig()) {
            <!-- Systems Table -->
            <div class="flex flex-col gap-xs">
              <span class="text-sm font-medium">Systems</span>
              <table style="width: 100%; border-collapse: collapse">
                <thead>
                  <tr class="border-b">
                    <th class="text-sm font-medium p-xs" style="text-align: left">System</th>
                    <th class="text-sm font-medium p-xs" style="text-align: left">Category</th>
                    <th class="text-sm font-medium p-xs" style="text-align: left">Operational State</th>
                    <th class="text-sm font-medium p-xs" style="text-align: left">Power</th>
                  </tr>
                </thead>
                <tbody>
                  @for (sys of domainConfig()!.systems; track sys.id) {
                    <tr class="border-b">
                      <td class="text-sm p-xs">{{ sys.label }}</td>
                      <td class="text-sm p-xs">{{ sys.category }}</td>
                      <td class="p-xs">
                        <select
                          class="input-base"
                          [value]="getSystemOpState(sys.id)"
                          (change)="onSystemOpStateChange(sys.id, $event)"
                        >
                          <option value="green">Green</option>
                          <option value="yellow">Yellow</option>
                          <option value="red">Red</option>
                        </select>
                      </td>
                      <td class="p-xs">
                        <select
                          class="input-base"
                          [value]="getSystemPower(sys.id)"
                          (change)="onSystemPowerChange(sys.id, $event)"
                        >
                          <option value="true">ON</option>
                          <option value="false">OFF</option>
                        </select>
                      </td>
                    </tr>
                  }
                </tbody>
              </table>
            </div>

            <!-- Warfare Domains Table -->
            <div class="flex flex-col gap-xs">
              <span class="text-sm font-medium">Warfare Domains</span>
              <table style="width: 100%; border-collapse: collapse">
                <thead>
                  <tr class="border-b">
                    <th class="text-sm font-medium p-xs" style="text-align: left">Domain</th>
                    <th class="text-sm font-medium p-xs" style="text-align: left">Threat Level</th>
                  </tr>
                </thead>
                <tbody>
                  @for (dom of domainConfig()!.warfare_domains; track dom.id) {
                    <tr class="border-b">
                      <td class="text-sm p-xs">{{ dom.label }}</td>
                      <td class="p-xs">
                        <select
                          class="input-base"
                          [value]="getDomainThreatLevel(dom.id)"
                          (change)="onDomainThreatChange(dom.id, dom.label, $event)"
                        >
                          <option value="green">Green</option>
                          <option value="red">Red</option>
                        </select>
                      </td>
                    </tr>
                  }
                </tbody>
              </table>
            </div>
          } @else {
            <p class="text-sm text-muted-foreground">
              Loading foundation data...
            </p>
          }
        </div>
      </ui-card>
    </section>
  `,
})
export class ScenarioSetupTabComponent implements OnInit {
  protected readonly store = inject(ScenarioBuilderStore);
  private readonly domainConfigApi = inject(DomainConfigApiService);

  protected readonly domainConfig = signal<DomainConfigResponse | null>(null);

  protected readonly objectives = computed(
    () => this.store.content().objectives ?? [],
  );
  protected readonly rules = computed(
    () => this.store.content().rules ?? [],
  );
  protected readonly gameMode = computed(
    () => this.store.content().game_mode ?? "classic",
  );
  protected readonly thresholdLo = computed(
    () => this.store.content().score_tier_thresholds?.["lo"] ?? 0,
  );
  protected readonly thresholdMid = computed(
    () => this.store.content().score_tier_thresholds?.["mid"] ?? 0,
  );

  ngOnInit(): void {
    this.domainConfigApi.getBySlug("silent-wake").subscribe({
      next: (config) => this.domainConfig.set(config),
    });
  }

  // --- Briefing ---
  protected onBriefingChange(event: Event): void {
    const target = event.target;
    if (target instanceof HTMLTextAreaElement) {
      this.store.setBriefing(target.value);
    }
  }

  // --- Objectives ---
  protected addObjective(): void {
    this.store.setObjectives([...this.objectives(), ""]);
  }

  protected removeObjective(index: number): void {
    const updated = this.objectives().filter((_, i) => i !== index);
    this.store.setObjectives(updated);
  }

  protected onObjectiveChange(index: number, event: Event): void {
    const target = event.target;
    if (!(target instanceof HTMLInputElement)) return;
    const updated = [...this.objectives()];
    updated[index] = target.value;
    this.store.setObjectives(updated);
  }

  // --- Rules ---
  protected addRule(): void {
    this.store.setRules([...this.rules(), ""]);
  }

  protected removeRule(index: number): void {
    const updated = this.rules().filter((_, i) => i !== index);
    this.store.setRules(updated);
  }

  protected onRuleChange(index: number, event: Event): void {
    const target = event.target;
    if (!(target instanceof HTMLInputElement)) return;
    const updated = [...this.rules()];
    updated[index] = target.value;
    this.store.setRules(updated);
  }

  // --- Score Tier Thresholds ---
  protected onThresholdLoChange(event: Event): void {
    const target = event.target;
    if (!(target instanceof HTMLInputElement)) return;
    const val = parseFloat(target.value);
    if (isNaN(val)) return;
    const current = this.store.content().score_tier_thresholds ?? {};
    this.store.setScoreTierThresholds({ ...current, lo: val });
  }

  protected onThresholdMidChange(event: Event): void {
    const target = event.target;
    if (!(target instanceof HTMLInputElement)) return;
    const val = parseFloat(target.value);
    if (isNaN(val)) return;
    const current = this.store.content().score_tier_thresholds ?? {};
    this.store.setScoreTierThresholds({ ...current, mid: val });
  }

  // --- Time Factor ---
  protected onTimeFactorChange(event: Event): void {
    const target = event.target;
    if (!(target instanceof HTMLInputElement)) return;
    const val = parseFloat(target.value);
    if (val > 0) this.store.setTimeFactor(val);
  }

  // --- System State Overrides ---
  protected getSystemOpState(systemId: string): string {
    const states = this.store.content().initial_system_states ?? [];
    const found = states.find((s) => s.system_id === systemId);
    return found?.operational_state ?? "green";
  }

  protected getSystemPower(systemId: string): string {
    const states = this.store.content().initial_system_states ?? [];
    const found = states.find((s) => s.system_id === systemId);
    return String(found?.power_state ?? true);
  }

  protected onSystemOpStateChange(systemId: string, event: Event): void {
    const target = event.target;
    if (!(target instanceof HTMLSelectElement)) return;
    this.updateSystemState(systemId, { operational_state: target.value });
  }

  protected onSystemPowerChange(systemId: string, event: Event): void {
    const target = event.target;
    if (!(target instanceof HTMLSelectElement)) return;
    this.updateSystemState(systemId, {
      power_state: target.value === "true",
    });
  }

  private updateSystemState(
    systemId: string,
    updates: Partial<SystemStateDef>,
  ): void {
    const states = [...(this.store.content().initial_system_states ?? [])];
    const idx = states.findIndex((s) => s.system_id === systemId);
    if (idx >= 0) {
      states[idx] = { ...states[idx], ...updates };
    } else {
      states.push({
        system_id: systemId,
        operational_state: "green",
        power_state: true,
        ...updates,
      });
    }
    this.store.setInitialSystemStates(states);
  }

  // --- Warfare Domain Overrides ---
  protected getDomainThreatLevel(domainId: string): string {
    const domains = this.store.content().initial_warfare_domains ?? [];
    const found = domains.find((d) => d.domain_id === domainId);
    return found?.initial_threat_level ?? "green";
  }

  protected onDomainThreatChange(
    domainId: string,
    label: string,
    event: Event,
  ): void {
    const target = event.target;
    if (!(target instanceof HTMLSelectElement)) return;
    const domains = [
      ...(this.store.content().initial_warfare_domains ?? []),
    ];
    const idx = domains.findIndex((d) => d.domain_id === domainId);
    if (idx >= 0) {
      domains[idx] = {
        ...domains[idx],
        initial_threat_level: target.value,
      };
    } else {
      domains.push({
        domain_id: domainId,
        label,
        initial_threat_level: target.value,
      });
    }
    this.store.setInitialWarfareDomains(domains);
  }
}

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  inject,
  OnInit,
  signal,
} from "@angular/core";
import {
  ButtonDirective,
  CollapsiblePanelComponent,
  SidebarLayoutComponent,
} from "@aspect/ui";
import { ScenarioApiService } from "../../core/scenario-api.service";
import { ScenarioBuilderStore } from "./scenario-builder.store";
import { ScenarioBuilderActionsComponent } from "./scenario-builder-view-actions";
import { ScenarioSidebarNavComponent } from "./scenario-sidebar-nav";
import type { SidebarSection } from "./scenario-sidebar-nav";
import { ScenarioSetupTabComponent } from "./scenario-setup-tab";
import { validateScenarioContent } from "./validate-scenario-content";

@Component({
  selector: "tfc-scenario-builder-view",
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [ScenarioBuilderStore],
  imports: [
    ButtonDirective,
    CollapsiblePanelComponent,
    SidebarLayoutComponent,
    ScenarioBuilderActionsComponent,
    ScenarioSidebarNavComponent,
    ScenarioSetupTabComponent,
  ],
  template: `
    <ui-sidebar-layout
      side="left"
      style="--sidebar-width: 14rem; height: 100dvh"
    >
      <div
        sidebar
        class="flex flex-col gap-md p-sm"
        style="height: 100%; overflow-y: auto"
      >
        <tfc-scenario-sidebar-nav
          [sections]="sidebarSections()"
          [activeSection]="''"
        />
        <ui-collapsible-panel>
          <span panelTitle>Existing Scenarios</span>
          @for (s of scenarios(); track s.id) {
            <div class="flex items-center justify-between p-sm border-b">
              <span
                class="text-sm font-medium cursor-pointer"
                (click)="loadScenario(s.id)"
              >
                {{ s.title }}
              </span>
              <button
                uiButton
                variant="destructive"
                size="sm"
                (click)="deleteScenario(s.id)"
              >
                Delete
              </button>
            </div>
          } @empty {
            <p class="text-muted-foreground text-sm p-sm">
              No scenarios found.
            </p>
          }
        </ui-collapsible-panel>
      </div>

      <div class="flex flex-col gap-md p-lg" style="overflow-y: auto">
        <tfc-scenario-builder-actions
          [viewMode]="viewMode()"
          [isDirty]="isDirty()"
          (onSave)="save()"
          (onSaveAsCopy)="saveAsCopy()"
          (onToggleView)="
            viewMode.set(viewMode() === 'setup' ? 'turns' : 'setup')
          "
        />

        @if (store.error()) {
          <div
            class="p-sm border border-destructive bg-destructive/10 text-destructive text-sm rounded"
            role="alert"
          >
            <strong>Validation errors:</strong>
            <ul class="mt-xs ml-md list-disc">
              @for (err of store.error()!.split("\\n"); track err) {
                <li>{{ err }}</li>
              }
            </ul>
          </div>
        }

        @if (viewMode() === "setup") {
          <tfc-scenario-setup-tab />
        } @else {
          <p class="text-muted-foreground text-sm p-lg">
            Turns editor coming soon...
          </p>
        }
      </div>
    </ui-sidebar-layout>
  `,
})
export class ScenarioBuilderView implements OnInit {
  protected readonly store = inject(ScenarioBuilderStore);
  private readonly api = inject(ScenarioApiService);
  protected readonly scenarios = signal<{ id: number; title: string }[]>([]);

  protected readonly viewMode = signal<"setup" | "turns">("setup");

  protected readonly isDirty = computed(() => {
    const snap = this.store.loadedSnapshot();
    if (!snap) return false;
    const current = JSON.stringify({
      title: this.store.title(),
      description: this.store.description(),
      content: this.store.content(),
    });
    return current !== snap;
  });

  protected readonly sidebarSections = computed<SidebarSection[]>(() => [
    { id: "foundation", label: "Foundation", count: 0 },
    { id: "metadata", label: "Metadata", count: 0 },
    { id: "initial-states", label: "Initial States", count: 0 },
  ]);

  ngOnInit(): void {
    this.loadList();
  }

  private loadList(): void {
    this.api.list().subscribe({
      next: (list) =>
        this.scenarios.set(list.map((s) => ({ id: s.id, title: s.title }))),
    });
  }

  protected loadScenario(id: number): void {
    this.api.get(id).subscribe({
      next: (s) =>
        this.store.loadScenario(s.id, s.title, s.description, s.content),
    });
  }

  protected save(): void {
    this.store.clearError();
    const content = this.store.content();
    const errors = validateScenarioContent(content);
    if (!this.store.title().trim()) errors.unshift("Title is required.");
    if (errors.length > 0) {
      this.store.setError(errors.join("\n"));
      return;
    }
    this.store.setSaving(true);
    const payload = {
      title: this.store.title(),
      description: this.store.description(),
      content,
    };
    const id = this.store.scenarioId();
    const req = id ? this.api.update(id, payload) : this.api.create(payload);
    req.subscribe({
      next: (s) => {
        this.store.loadScenario(s.id, s.title, s.description, s.content);
        this.store.setSaving(false);
        this.loadList();
      },
      error: () =>
        this.store.setError("Save failed — server rejected the scenario."),
    });
  }

  protected saveAsCopy(): void {
    const id = this.store.scenarioId();
    if (!id) return;
    this.store.setSaving(true);
    this.api.clone(id).subscribe({
      next: (s) => {
        this.store.loadScenario(s.id, s.title, s.description, s.content);
        this.store.setSaving(false);
        this.loadList();
      },
      error: () => {
        this.store.setSaving(false);
        this.store.setError("Clone failed.");
      },
    });
  }

  protected deleteScenario(id: number): void {
    this.api.delete(id).subscribe({ next: () => this.loadList() });
  }
}

