  8→/** Return a new content with the turn appended and its turn_index auto-set. */
  9→export function addTurn(
 10→  content: ScenarioContent,
 11→  turn: TurnDefinition,
 12→): ScenarioContent {
 13→  const turns = content.turns ?? [];
 14→  return { ...content, turns: [...turns, { ...turn, turn_index: turns.length }] };
