134→): ScenarioContent {
135→  const turns = (content.turns ?? []).map((t) =>
136→    t.turn_index === turnIndex
137→      ? {
138→          ...t,
139→          available_cards: t.available_cards.filter(
140→            (c) => c.card_id !== cardId,
141→          ),
142→        }
143→      : t,
144→  );
145→  return { ...content, turns };
146→}
147→
148→/** Update a card in the turn's available_cards by card_id. */
149→export function updateCardInTurn(
150→  content: ScenarioContent,
151→  turnIndex: number,
152→  cardId: string,
153→  updates: Partial<TurnCardConfig>,
154→): ScenarioContent {
155→  const turns = (content.turns ?? []).map((t) =>
156→    t.turn_index === turnIndex
157→      ? {
158→          ...t,
159→          available_cards: t.available_cards.map((c) =>
160→            c.card_id === cardId ? { ...c, ...updates } : c,
161→          ),
162→        }
163→      : t,
164→  );
165→  return { ...content, turns };
166→}
