113→  private readonly api = inject(ScenarioApiService);
114→  protected readonly scenarios = signal<{ id: number; title: string }[]>([]);
115→
116→  protected readonly viewMode = signal<"setup" | "turns">("setup");
117→
118→  protected readonly isDirty = computed(() => {
119→    const snap = this.store.loadedSnapshot();
120→    if (!snap) return false;
121→    const current = JSON.stringify({
122→      title: this.store.title(),
123→      description: this.store.description(),
124→      content: this.store.content(),
125→    });
126→    return current !== snap;
127→  });
128→
129→  protected readonly sidebarSections = computed<SidebarSection[]>(() => [
130→    { id: "foundation", label: "Foundation", count: 0 },
131→    { id: "metadata", label: "Metadata", count: 0 },
132→    { id: "initial-states", label: "Initial States", count: 0 },
133→  ]);
134→
135→  ngOnInit(): void {
136→    this.loadList();
137→  }
138→
139→  private loadList(): void {
140→    this.api.list().subscribe({
141→      next: (list) =>
142→        this.scenarios.set(list.map((s) => ({ id: s.id, title: s.title }))),
143→    });
144→  }
