146→  protected loadScenario(id: number): void {
147→    this.api.get(id).subscribe({
148→      next: (s) =>
149→        this.store.loadScenario(s.id, s.title, s.description, s.content),
150→    });
151→  }
152→
153→  protected save(): void {
154→    this.store.clearError();
155→    const content = this.store.content();
156→    const errors = validateScenarioContent(content);
157→    if (!this.store.title().trim()) errors.unshift("Title is required.");
158→    if (errors.length > 0) {
159→      this.store.setError(errors.join("\n"));
160→      return;
161→    }
162→    this.store.setSaving(true);
163→    const payload = {
164→      title: this.store.title(),
165→      description: this.store.description(),
166→      content,
167→    };
168→    const id = this.store.scenarioId();
169→    const req = id ? this.api.update(id, payload) : this.api.create(payload);
170→    req.subscribe({
171→      next: (s) => {
172→        this.store.loadScenario(s.id, s.title, s.description, s.content);
173→        this.store.setSaving(false);
174→        this.loadList();
175→      },
176→      error: () =>
177→        this.store.setError("Save failed — server rejected the scenario."),
178→    });
179→  }
180→
